"""Import tabular battery-cycle data into the normalized MVP schema."""

from __future__ import annotations

import json
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path

import pandas as pd

REQUIRED_FIELDS = ("cell_id", "cycle_index", "capacity_ah")


class DataImportError(ValueError):
    """Raised when source data cannot satisfy the normalized data contract."""


@dataclass(frozen=True)
class ImportResult:
    """Paths generated by a successful import."""

    normalized_path: Path
    quality_report_path: Path


def _validate_mapping(columns: pd.Index[str], field_mapping: Mapping[str, str]) -> None:
    missing_mapping = [field for field in REQUIRED_FIELDS if field not in field_mapping]
    if missing_mapping:
        joined = ", ".join(missing_mapping)
        raise DataImportError(f"Field mapping is missing required field(s): {joined}")

    missing_source = [
        canonical for canonical in REQUIRED_FIELDS if field_mapping[canonical] not in columns
    ]
    if missing_source:
        joined = ", ".join(missing_source)
        raise DataImportError(f"Input data is missing required field(s): {joined}")


def _normalize(frame: pd.DataFrame, field_mapping: Mapping[str, str]) -> pd.DataFrame:
    normalized = frame[[field_mapping[field] for field in REQUIRED_FIELDS]].rename(
        columns={source: canonical for canonical, source in field_mapping.items()}
    )

    if (
        normalized["cell_id"].isna().any()
        or (normalized["cell_id"].astype(str).str.strip() == "").any()
    ):
        raise DataImportError("Input data contains an empty cell_id")

    try:
        normalized["cycle_index"] = pd.to_numeric(normalized["cycle_index"], errors="raise").astype(
            "int64"
        )
        normalized["capacity_ah"] = pd.to_numeric(normalized["capacity_ah"], errors="raise").astype(
            "float64"
        )
    except (TypeError, ValueError) as error:
        raise DataImportError("cycle_index and capacity_ah must be numeric") from error

    normalized["cell_id"] = normalized["cell_id"].astype(str)
    return normalized


def import_cycle_csv(
    *,
    input_path: Path,
    output_dir: Path,
    field_mapping: Mapping[str, str],
) -> ImportResult:
    """Import a CSV file and write normalized cycles plus a portable quality report."""

    try:
        source = pd.read_csv(input_path)
    except (OSError, pd.errors.ParserError) as error:
        raise DataImportError(f"Unable to read input CSV: {input_path.name}") from error

    _validate_mapping(source.columns, field_mapping)
    normalized = _normalize(source, field_mapping)

    output_dir.mkdir(parents=True, exist_ok=True)
    normalized_path = output_dir / "cycles.csv"
    quality_report_path = output_dir / "quality_report.json"

    report = {
        "input_file": input_path.name,
        "cell_count": int(normalized["cell_id"].nunique()),
        "cycle_count": int(len(normalized)),
        "fields": list(REQUIRED_FIELDS),
        "units": {"capacity_ah": "Ah"},
    }

    normalized.to_csv(normalized_path, index=False)
    quality_report_path.write_text(
        json.dumps(report, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    return ImportResult(
        normalized_path=normalized_path,
        quality_report_path=quality_report_path,
    )
